from polymarket_debounced_signals import build as build_debounced, METHOD as DEBOUNCED_METHOD, display_tables
from polymarket_signal_quality import MODEL_LABELS
debounced = build_debounced()
display(Markdown(DEBOUNCED_METHOD))
table(pd.DataFrame(MODEL_LABELS.items(),columns=['Code','Model']))
for cycle, rows in debounced['overall'].groupby('cycle'):
    display(Markdown(f'### {cycle}: distinct setups and hindsight path diagnostics'))
    for view in display_tables(rows):
        table(view)
    table(rows[['model','mean_raw_max_cents','mean_worst_cents','median_sustained_return_pct']].rename(columns={
        'model':'Model','mean_raw_max_cents':'Mean raw max (¢)','mean_worst_cents':'Mean worst change (¢)',
        'median_sustained_return_pct':'Median max sustained (%)'}))
for key, band in [('probabilities','probability_band'),('time','time_band'),('activity','activity_band'),('states','state')]:
    for (cycle,label), rows in debounced[key].groupby(['cycle',band]):
        display(Markdown(f'#### {cycle}: {key} — {label}'))
        for view in display_tables(rows):
            table(view)
print('Debounced report:',debounced['report'].relative_to(ROOT))
print('Saved setup rows: outputs/results/research/polymarket_history/debounced_win_episodes.parquet')
print('Saved daily checks and price paths: debounced_win_decisions.parquet and debounced_win_paths.parquet in the same folder.')

table(research['coverage'].rename(columns={'cycle':'Cycle','price_source':'Source','contracts':'Markets','points':'Daily points'}))
if (OUT / 'publisher_status.parquet').exists():
    table(pd.read_parquet(OUT / 'publisher_status.parquet')[['model','cycle','status','rows','first','last']])

from polymarket_history_samples import state_comparison_table, proximity, overall_proximity
samples = research['date_samples']
for path in research['charts']:
    if path.name.startswith('prediction_comparison'):
        display(Image(filename=str(path)))
for (cycle, date), group in research['scores'].groupby(['cycle','check_date']):
    display(Markdown(f'### {cycle} — {date:%b %d}'))
    table(group[['model','priced_states','model_brier','market_brier','gap_pp']].rename(columns={
        'model':'Model','priced_states':'States','model_brier':'Brier','market_brier':'Market Brier','gap_pp':'Gap (pp)'}))
near = research['state_proximity']
for cycle, group in near.groupby('cycle'):
    display(Markdown(f'### {cycle} — models closest to the market'))
    rank = overall_proximity(group).rename(columns={'model':'Model','states':'States','gap_pp':'Gap (pp)','brier':'Brier'})
    table(rank)

from polymarket_accuracy_evolution import METHOD, score_table
study = research['evolution']
display(Markdown(METHOD))
for row in study['coverage'].itertuples():
    print(f'{row.cycle}: {row.states} states across {row.dates} dates. Included: {row.included}.')
    print('Excluded from this fixed panel:', row.excluded)
for path in research['charts']:
    if path.name.startswith('accuracy_evolution'):
        display(Image(filename=str(path)))
for (cycle, cohort), rows in study['metrics'].groupby(['cycle','cohort']):
    display(Markdown(f'### {cycle} — {cohort} ({rows.races.iloc[0]} races)'))
    table(score_table(rows))
display(Markdown('### Long shots selected at each date'))
display(Markdown('The same market-defined underdogs are scored by every model. Expected wins sum their probabilities. Counts matter: small groups and repeated outcomes do not establish rare-event calibration.'))
for (cycle, date), rows in study['longshots'].groupby(['cycle','check_date']):
    display(Markdown(f'**{cycle} — {date:%b %d}**'))
    table(rows[['model','races','expected_wins','actual_wins','brier']].rename(columns={
        'model':'Model','races':'Races','expected_wins':'Expected wins','actual_wins':'Actual wins','brier':'Brier'}))
display(Markdown('### Each state: Brier score through time'))
for (cycle, state), rows in study['panel'].groupby(['cycle','state']):
    display(Markdown(f'**{cycle} — {state} · final winner: {rows.final_winner.iloc[0]}**'))
    table(score_table(rows))
